/* a flame: a teardrop of orange with a yellow core, centred at x,y, height s */
function IC_flame(x,y,s,col){return `<path d="M${x},${y-s/2} C${x+s*.42},${y-s*.1} ${x+s*.38},${y+s*.42} ${x},${y+s/2} C${x-s*.38},${y+s*.42} ${x-s*.42},${y-s*.1} ${x},${y-s/2} Z" fill="${col||ORG}"/><path d="M${x},${y-s*.12} C${x+s*.2},${y+s*.08} ${x+s*.18},${y+s*.4} ${x},${y+s*.44} C${x-s*.18},${y+s*.4} ${x-s*.2},${y+s*.08} ${x},${y-s*.12} Z" fill="#FFD43B"/>`}
function EXTRA(R,ICON){
 /* hook: four plug leads with two swapped, and a spark on the wrong stroke */
 ICON.icLeads=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${IC_box(0,0,380,160,{fill:'#FFFFFF',st:IC_GREY,sw:3,r:18})}
  ${[0,1,2,3].map(i=>`<circle cx="${70+i*80}" cy="118" r="22" fill="${IC_AL}" stroke="${IC_STEEL}" stroke-width="3"/>`+IC_T(70+i*80,126,String(i+1),{fs:22,fw:800,a:'middle'})).join('')}
  <rect x="250" y="14" width="80" height="34" rx="6" fill="${IC_DARK}"/>${IC_T(290,38,'coil',{fs:20,fw:800,a:'middle',fill:'#FFFFFF'})}
  <path d="M260,48 Q120,52 70,96" stroke="${IC_GREY}" stroke-width="4" fill="none"/><path d="M320,48 Q330,70 310,96" stroke="${IC_GREY}" stroke-width="4" fill="none"/>
  <path d="M280,48 Q270,74 150,96" stroke="${RED}" stroke-width="5" fill="none"/><path d="M300,48 Q290,74 230,96" stroke="${RED}" stroke-width="5" fill="none"/>
  ${IC_T(20,34,'leads 2 and 3',{fs:20,fw:800,fill:RED})}${IC_T(20,58,'swapped',{fs:20,fw:800,fill:RED})}</g>`;
 ICON.icWrong=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${IC_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}
  ${IC_L(44,22,44,130,IC_DARK,5)}${IC_L(124,22,124,130,IC_DARK,5)}${IC_L(34,22,134,22,IC_DARK,7)}<rect x="80" y="8" width="8" height="16" fill="${IC_STEEL}"/>
  <polyline points="78,30 90,40 80,46 92,56" fill="none" stroke="#FFD43B" stroke-width="5" stroke-linejoin="round"/>
  <rect x="48" y="62" width="72" height="22" rx="4" fill="${IC_AL}" stroke="${IC_STEEL}" stroke-width="3"/>${IC_arrow(150,110,150,60,IC_DARK,4)}
  ${IC_T(170,52,'spark at the end',{fs:22,fw:800,fill:ORG})}${IC_T(170,82,'of exhaust',{fs:22,fw:800,fill:ORG})}${IC_T(170,124,'no charge to burn',{fs:20,fill:IC_GREY})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.icValve=(x,y)=>`<g transform="translate(${x} ${y}) scale(1.16) translate(-210 -165)">${IC_dial(210,175,118,{bdc:false})}${IC_arc(210,175,92,-10,220,BLU,14)}${IC_arc(210,175,118,135,370,ORG,14)}${IC_wedge(210,175,82,-10,10,GRN,.5)}
  ${IC_T(10,70,'IVO',{fs:22,fw:800,fill:BLU})}${IC_T(360,70,'EVC',{fs:22,fw:800,fill:ORG})}${IC_T(10,300,'IVC',{fs:22,fw:800,fill:BLU})}${IC_T(360,250,'EVO',{fs:22,fw:800,fill:ORG})}</g>`;
 ICON.icPort=(x,y)=>`<g transform="translate(${x} ${y}) scale(1.16) translate(-210 -165)">${IC_dial(210,175,118,{bdc:false})}${IC_arc(210,175,118,120,240,ORG,14)}${IC_arc(210,175,94,135,225,BLU,14)}${IC_arc(210,175,70,-55,55,GRN,14)}
  ${IC_T(10,70,'inlet',{fs:22,fw:800,fill:GRN})}${IC_T(10,250,'transfer',{fs:22,fw:800,fill:BLU})}${IC_T(330,250,'exhaust',{fs:22,fw:800,fill:ORG})}</g>`;
 ICON.icFire=(x,y)=>`<g transform="translate(${x} ${y}) scale(1.16) translate(-210 -165)">${IC_row(60,200,100,4,40,i=>'#EBFBEE')}
  ${[[60,1],[160,4],[260,2],[360,3]].map(([cx,k])=>`<circle cx="${cx+28}" cy="${150}" r="18" fill="${GRN}"/>`+IC_T(cx+28,158,String(k),{fs:20,fw:800,a:'middle',fill:'#FFFFFF'})).join('')}
  ${[0,1,2,3].map(i=>IC_flame(60+i*100,82,44)).join('')}
  ${IC_T(210,300,'firing order 1-3-4-2',{fs:24,fw:800,a:'middle',fill:GRN})}</g>`;
}
